package horizon.javalayer;

import org.bukkit.Material;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;

/**
 * Item stacks. Paper's `ItemStack` hands everything to a delegate (CraftItemStack there); here the delegate is
 * an {@code HItemStack} (generated by Gen), whose every method is the server's item.
 */
public final class Items {
    private Items() {}

    private static final Field DELEGATE;

    static {
        Field f = null;
        try {
            f = ItemStack.class.getDeclaredField("craftDelegate");
            f.setAccessible(true);
        } catch (ReflectiveOperationException ignored) {}
        DELEGATE = f;
    }

    public static ItemStack wrap(H h) {
        return new HItemStack(h);
    }


    /** A new server item of this material and amount. */
    public static ItemStack create(Material material, int amount) {
        Object raw = Native.construct("ItemStack", new Object[]{Pack.of(Pack.MAT, material.getKey().toString()), amount});
        if (raw instanceof H h) return wrap(h);
        throw new IllegalStateException("the server made no item for " + material);
    }

    static Object toNative(ItemStack stack) {
        H h = Proxies.handleOf(stack);
        if (h != null) return h;
        if (DELEGATE != null) {
            try {
                Object delegate = DELEGATE.get(stack);
                H inner = Proxies.handleOf(delegate);
                if (inner != null) return inner;
            } catch (IllegalAccessException ignored) {}
        }
        // A stack some other way (a plugin's own subclass): a server item of its type and amount.
        Object made = toNative(create(stack.getType(), stack.getAmount()));
        return made;
    }

    private static final Map<String, List<Class<?>>> META = new ConcurrentHashMap<>();

    private static Class<?> meta(String simple) {
        try {
            return Class.forName(simple.contains(".") ? simple : "org.bukkit.inventory.meta." + simple, false, Items.class.getClassLoader());
        } catch (ClassNotFoundException e) {
            return null;
        }
    }

    private static final java.util.Set<String> HEADS = java.util.Set.of("CREEPER_HEAD", "DRAGON_HEAD", "PIGLIN_HEAD", "PLAYER_HEAD", "SKELETON_SKULL", "WITHER_SKELETON_SKULL", "ZOMBIE_HEAD");
    /** Block items whose block has a block entity (vanilla's EntityBlock) and no meta of their own before it. */
    private static final java.util.Set<String> BLOCK_ENTITY_ITEMS = java.util.Set.of("CHEST", "TRAPPED_CHEST", "ENDER_CHEST", "BARREL",
            "FURNACE", "BLAST_FURNACE", "SMOKER", "HOPPER", "DISPENSER", "DROPPER", "BREWING_STAND", "BEACON", "SPAWNER", "TRIAL_SPAWNER", "VAULT",
            "COMMAND_BLOCK", "CHAIN_COMMAND_BLOCK", "REPEATING_COMMAND_BLOCK", "STRUCTURE_BLOCK", "JIGSAW", "CAMPFIRE", "SOUL_CAMPFIRE", "LECTERN",
            "BELL", "JUKEBOX", "CONDUIT", "ENCHANTING_TABLE", "DAYLIGHT_DETECTOR", "COMPARATOR", "BEEHIVE", "BEE_NEST", "SCULK_SENSOR",
            "CALIBRATED_SCULK_SENSOR", "SCULK_SHRIEKER", "SCULK_CATALYST", "CHISELED_BOOKSHELF", "DECORATED_POT", "SUSPICIOUS_SAND",
            "SUSPICIOUS_GRAVEL", "CRAFTER", "CREAKING_HEART", "TEST_BLOCK", "TEST_INSTANCE_BLOCK");

    private static final Map<String, Optional<Class<?>>> META_CLASS = new java.util.concurrent.ConcurrentHashMap<>();

    /** Paper 26.3's meta class of each item (resources/horizon/meta-classes.txt, from Paper itself: MATERIAL CraftMetaX). */
    private static volatile Map<String, String> PAPER_META;

    static Map<String, String> paperMeta() {
        Map<String, String> m = PAPER_META;
        if (m != null) return m;
        Map<String, String> out = new java.util.HashMap<>();
        try (var in = Items.class.getResourceAsStream("/horizon/meta-classes.txt")) {
            if (in != null) {
                for (String line : new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8).split("\\R")) {
                    String[] parts = line.trim().split(" ");
                    if (parts.length == 2) out.put(parts[0], parts[1]);
                }
            }
        } catch (java.io.IOException ignored) {
        }
        PAPER_META = out;
        return out;
    }

    /** Each Paper meta class's interfaces (its kind, as metaKind gives it): null for a plain one. */
    private static final Map<String, String> KIND_OF = Map.ofEntries(
            Map.entry("CraftMetaBookSigned", "BookMeta"), Map.entry("CraftMetaBook", "WritableBookMeta,BookMeta"),
            Map.entry("CraftMetaSkull", "SkullMeta"), Map.entry("CraftMetaArmor", "ArmorMeta"),
            Map.entry("CraftMetaColorableArmor", "ColorableArmorMeta,LeatherArmorMeta,ArmorMeta"), Map.entry("CraftMetaLeatherArmor", "LeatherArmorMeta"),
            Map.entry("CraftMetaPotion", "PotionMeta"), Map.entry("CraftMetaMap", "MapMeta"), Map.entry("CraftMetaFirework", "FireworkMeta"),
            Map.entry("CraftMetaCharge", "FireworkEffectMeta"), Map.entry("CraftMetaEnchantedBook", "EnchantmentStorageMeta"),
            Map.entry("CraftMetaBanner", "BannerMeta"), Map.entry("CraftMetaSpawnEgg", "SpawnEggMeta"),
            Map.entry("CraftMetaArmorStand", "com.destroystokyo.paper.inventory.meta.ArmorStandMeta"), Map.entry("CraftMetaKnowledgeBook", "KnowledgeBookMeta"),
            Map.entry("CraftMetaBlockState", "BlockStateMeta"), Map.entry("CraftMetaShield", "ShieldMeta,BlockStateMeta"),
            Map.entry("CraftMetaTropicalFishBucket", "TropicalFishBucketMeta"), Map.entry("CraftMetaAxolotlBucket", "AxolotlBucketMeta"),
            Map.entry("CraftMetaCrossbow", "CrossbowMeta"), Map.entry("CraftMetaSuspiciousStew", "SuspiciousStewMeta"),
            Map.entry("CraftMetaCompass", "CompassMeta"), Map.entry("CraftMetaBundle", "BundleMeta"),
            Map.entry("CraftMetaMusicInstrument", "MusicInstrumentMeta"), Map.entry("CraftMetaOminousBottle", "OminousBottleMeta"));

    /** The meta class for this material: Paper's own (org.bukkit.craftbukkit.inventory.CraftMeta*, made by Gen.metas). */
    static Class<?> metaClass(String material) {
        String k = material == null ? "" : material.toUpperCase(Locale.ROOT);
        return META_CLASS.computeIfAbsent(k, key -> {
            String name = paperMeta().get(key);
            if (name == null) {
                String kind = legacyKind(key);
                name = "CraftMetaItem";
                if (kind != null) for (Map.Entry<String, String> e : KIND_OF.entrySet()) if (e.getValue().equals(kind)) name = e.getKey();
            }
            try {
                return Optional.of(Class.forName("org.bukkit.craftbukkit.inventory." + name, true, Items.class.getClassLoader()));
            } catch (ClassNotFoundException e) {
                return Optional.empty();
            }
        }).orElse(null);
    }

    /** The meta kind of an item (its meta interfaces), null for plain: from Paper's table, else the rules below. */
    static String metaKind(String k) {
        String name = paperMeta().get(k);
        if (name != null) return KIND_OF.get(name);
        return legacyKind(k);
    }

    /** Paper's CraftItemMetas.getItemMetaData, in its order (the first that fits): the meta kind of an item, null for plain. */
    static String legacyKind(String k) {
        if (k.equals("WRITTEN_BOOK")) return "BookMeta";
        if (k.equals("WRITABLE_BOOK")) return "WritableBookMeta,BookMeta";
        if (HEADS.contains(k)) return "SkullMeta";
        if (k.equals("TURTLE_HELMET") || k.matches("(CHAINMAIL|DIAMOND|GOLDEN|IRON|NETHERITE|COPPER)_(HELMET|CHESTPLATE|LEGGINGS|BOOTS)")) return "ArmorMeta";
        if (k.matches("LEATHER_(HELMET|CHESTPLATE|LEGGINGS|BOOTS)") || k.equals("WOLF_ARMOR")) return "ColorableArmorMeta,LeatherArmorMeta,ArmorMeta";
        if (k.equals("LEATHER_HORSE_ARMOR")) return "LeatherArmorMeta";
        if (k.equals("POTION") || k.equals("SPLASH_POTION") || k.equals("LINGERING_POTION") || k.equals("TIPPED_ARROW")) return "PotionMeta";
        if (k.equals("FILLED_MAP")) return "MapMeta";
        if (k.equals("FIREWORK_ROCKET")) return "FireworkMeta";
        if (k.equals("FIREWORK_STAR")) return "FireworkEffectMeta";
        if (k.equals("ENCHANTED_BOOK")) return "EnchantmentStorageMeta";
        if (k.endsWith("_BANNER") && !k.endsWith("_WALL_BANNER")) return "BannerMeta";
        if (k.endsWith("_SPAWN_EGG")) return "SpawnEggMeta";
        if (k.equals("ARMOR_STAND")) return "com.destroystokyo.paper.inventory.meta.ArmorStandMeta";
        if (k.equals("KNOWLEDGE_BOOK")) return "KnowledgeBookMeta";
        if (BLOCK_ENTITY_ITEMS.contains(k) || k.endsWith("SHULKER_BOX") || (k.endsWith("_SIGN") && !k.endsWith("_WALL_SIGN") && !k.endsWith("_WALL_HANGING_SIGN"))
                || (k.endsWith("_BED")) || k.endsWith("_SHELF") || k.endsWith("COPPER_GOLEM_STATUE")) return "BlockStateMeta";
        if (k.equals("SHIELD")) return "ShieldMeta,BlockStateMeta";
        if (k.equals("TROPICAL_FISH_BUCKET")) return "TropicalFishBucketMeta";
        if (k.equals("AXOLOTL_BUCKET")) return "AxolotlBucketMeta";
        if (k.equals("CROSSBOW")) return "CrossbowMeta";
        if (k.equals("SUSPICIOUS_STEW")) return "SuspiciousStewMeta";
        if (k.equals("COMPASS")) return "CompassMeta";
        if (k.endsWith("BUNDLE")) return "BundleMeta";
        if (k.equals("GOAT_HORN")) return "MusicInstrumentMeta";
        if (k.equals("OMINOUS_BOTTLE")) return "OminousBottleMeta";
        return null;
    }

    /** The meta interfaces an item of this material's meta has on Paper (CraftMetaSkull is a SkullMeta...). */
    static List<Class<?>> metaFaces(String material) {
        String m = material == null ? "" : material.toUpperCase(Locale.ROOT);
        return META.computeIfAbsent(m, k -> {
            List<String> names = new ArrayList<>(List.of("Damageable", "Repairable"));
            String kind = metaKind(k);
            if (kind != null) names.addAll(List.of(kind.split(",")));
            List<Class<?>> out = new ArrayList<>();
            for (String name : names) {
                Class<?> c = meta(name);
                if (c != null) out.add(c);
            }
            return out;
        });
    }

    /** HItemStack's methods: the server's item, with Java's own answers where Java logic is the API. */
    @SuppressWarnings("unchecked")
    public static Object invoke(HItemStack self, H h, Method m, Object[] args) {
        String name = m.getName();
        int n = args == null ? 0 : args.length;
        switch (name) {
            case "clone":
                if (n == 0) return wrap((H) Native.call(h, "clone", new Object[0]));
                break;
            case "equals":
                if (n == 1) {
                    if (!(args[0] instanceof ItemStack other)) return false;
                    if (other == self) return true;
                    return self.getAmount() == other.getAmount() && self.isSimilar(other);
                }
                break;
            case "isSimilar":
                // ItemStack.isSimilar: null (an empty slot) is never similar.
                if (n == 1 && args[0] == null) return false;
                if (n == 1 && args[0] == self) return true;
                break;
            case "hashCode":
                if (n == 0) return Objects.hash(self.getType(), self.getAmount());
                break;
            case "toString":
                // Bukkit's ItemStack.toString: the meta's own text (CraftMetaItem.toString) when the item has any
                // component of its own (CraftItemStack.hasItemMeta: a non-empty patch).
                if (n == 0) {
                    String all = Native.itemToJson(h);
                    com.google.gson.JsonElement listed = all == null ? null : com.google.gson.JsonParser.parseString(all).getAsJsonObject().get("components");
                    boolean patched = listed != null && listed.isJsonObject() && !listed.getAsJsonObject().isEmpty();
                    return "ItemStack{" + self.getType().name() + " x " + self.getAmount() + (patched ? ", " + self.getItemMeta() : "") + "}";
                }
                break;
            case "serialize":
                // CraftItemStack.serialize: DataVersion, id, count, components (each as the game prints its tag), schema_version.
                if (n == 0 && !self.getType().isAir() && self.getAmount() > 0) {
                    Map<String, Object> out = new java.util.LinkedHashMap<>();
                    out.put("DataVersion", org.bukkit.Bukkit.getUnsafe().getDataVersion());
                    out.put("id", self.getType().getKey().toString());
                    out.put("count", self.getAmount());
                    String all = Native.itemToJson(h);
                    com.google.gson.JsonElement listed = all == null ? null : com.google.gson.JsonParser.parseString(all).getAsJsonObject().get("components");
                    if (listed != null && listed.isJsonObject() && !listed.getAsJsonObject().isEmpty()) {
                        Map<String, Object> comps = new java.util.LinkedHashMap<>();
                        for (String id : listed.getAsJsonObject().keySet()) {
                            String one = Native.componentJson(h, id);
                            if (one != null) comps.put(id, PaperMeta.snbt(com.google.gson.JsonParser.parseString(one), id));
                        }
                        if (!comps.isEmpty()) out.put("components", comps);
                    }
                    out.put("schema_version", 1);
                    return out;
                }
                break;
            case "getMaxStackSize":
                if (n == 0) {
                    Object raw = Native.tryCall(h, "getMaxStackSize", new Object[0]);
                    int v = raw instanceof Number num ? num.intValue() : 0;
                    return v > 0 ? v : self.getType().getMaxStackSize();
                }
                break;
            case "editPersistentDataContainer":
                if (n == 1) {
                    ItemMeta meta = self.getItemMeta();
                    if (meta == null) return null;
                    ((Consumer<org.bukkit.persistence.PersistentDataContainer>) args[0]).accept(meta.getPersistentDataContainer());
                    self.setItemMeta(meta);
                    return null;
                }
                break;
            case "editMeta":
                if (n == 1) {
                    ItemMeta meta = self.getItemMeta();
                    if (meta == null) return false;
                    ((Consumer<ItemMeta>) args[0]).accept(meta);
                    return self.setItemMeta(meta);
                }
                if (n == 2) {
                    ItemMeta meta = self.getItemMeta();
                    if (!((Class<?>) args[0]).isInstance(meta)) return false;
                    ((Consumer<Object>) args[1]).accept(meta);
                    return self.setItemMeta(meta);
                }
                break;
            case "asOne":
                if (n == 0) { ItemStack c = self.clone(); c.setAmount(1); return c; }
                break;
            case "asQuantity":
                if (n == 1) { ItemStack c = self.clone(); c.setAmount((Integer) args[0]); return c; }
                break;
            case "withType":
                if (n == 1) { ItemStack c = self.clone(); c.setType((Material) args[0]); return c; }
                break;
            case "isEmpty":
                if (n == 0) {
                    // Paper: air or no items. (The SDK name "isEmpty" on an item means "no components".)
                    Material type = self.getType();
                    return type == null || type.isAir() || self.getAmount() <= 0;
                }
                break;
            case "ensureServerConversions":
                return self;
            case "getData":
                // Paper's DataComponentHolder.getData(type) (the old MaterialData getData() has no argument).
                if (n == 1 && args[0] instanceof io.papermc.paper.datacomponent.DataComponentType type) return Components.get(h, type);
                return null;
            case "setData":
                // A built component (an SDK object holding the game's JSON): set by its JSON, not as an object.
                if (n == 2 && args[0] instanceof io.papermc.paper.datacomponent.DataComponentType type && args[1] != null) {
                    Object nativeValue = Conv.toNative(args[1]);
                    String json = Native.valueJson(nativeValue);
                    if (json == null) json = Components.json(args[1]);
                    if (json != null) {
                        Native.setComponentJson(h, type.getKey().toString(), json);
                        return null;
                    }
                }
                break;
            case "getDataOrDefault":
                if (n == 2 && args[0] instanceof io.papermc.paper.datacomponent.DataComponentType type) {
                    Object v = Components.get(h, type);
                    return v != null ? v : args[1];
                }
                break;
            default:
                break;
        }
        Object raw = Native.tryCall(h, name, Conv.args(args));
        if (raw == Native.MISSING) {
            String where = "ItemStack." + name + "/" + n;
            NativeHandler.missing(where);
            throw Report.cant(where);
        }
        return Conv.fromNative(raw, m.getGenericReturnType());
    }
}
